import { getFormatMeta, type ImageOutputFormat } from './types';

/** Decodes any browser-readable image file onto a canvas at its native size. */
export async function loadImageToCanvas(file: File): Promise<HTMLCanvasElement> {
  let source: CanvasImageSource;
  let width: number;
  let height: number;
  let bitmap: ImageBitmap | null = null;

  try {
    bitmap = await createImageBitmap(file);
    source = bitmap;
    width = bitmap.width;
    height = bitmap.height;
  } catch {
    // Fallback for formats createImageBitmap won't touch in some browsers (e.g. older BMP/SVG support).
    const url = URL.createObjectURL(file);
    try {
      const img = await new Promise<HTMLImageElement>((resolve, reject) => {
        const el = new Image();
        el.onload = () => resolve(el);
        el.onerror = () => reject(new Error("This file couldn't be read as an image"));
        el.src = url;
      });
      source = img;
      width = img.naturalWidth;
      height = img.naturalHeight;
    } finally {
      URL.revokeObjectURL(url);
    }
  }

  if (!width || !height) throw new Error("This file couldn't be read as an image");

  const canvas = document.createElement('canvas');
  canvas.width = width;
  canvas.height = height;
  const ctx = canvas.getContext('2d');
  if (!ctx) throw new Error('Canvas is not supported in this browser');
  ctx.drawImage(source, 0, 0);
  bitmap?.close();

  return canvas;
}

/** Formats with no alpha channel (JPEG, BMP) need transparent pixels flattened onto a solid color first. */
function flattenOntoWhite(canvas: HTMLCanvasElement): HTMLCanvasElement {
  const flattened = document.createElement('canvas');
  flattened.width = canvas.width;
  flattened.height = canvas.height;
  const ctx = flattened.getContext('2d');
  if (!ctx) throw new Error('Canvas is not supported in this browser');
  ctx.fillStyle = '#ffffff';
  ctx.fillRect(0, 0, flattened.width, flattened.height);
  ctx.drawImage(canvas, 0, 0);
  return flattened;
}

export function canvasToBlob(canvas: HTMLCanvasElement, mimeType: string, quality?: number): Promise<Blob> {
  return new Promise((resolve, reject) => {
    canvas.toBlob(
      (blob) => (blob ? resolve(blob) : reject(new Error(`This browser can't encode ${mimeType}`))),
      mimeType,
      quality,
    );
  });
}

let webpSupportPromise: Promise<boolean> | null = null;

/** Older Safari versions can decode WebP but not encode it via canvas — detect once and cache. */
export function canEncodeWebp(): Promise<boolean> {
  if (!webpSupportPromise) {
    webpSupportPromise = (async () => {
      const probe = document.createElement('canvas');
      probe.width = 1;
      probe.height = 1;
      try {
        const blob = await canvasToBlob(probe, 'image/webp');
        return blob.type === 'image/webp';
      } catch {
        return false;
      }
    })();
  }
  return webpSupportPromise;
}

/** Hand-rolled 24-bit uncompressed BMP encoder — no browser exposes a native BMP encoder via canvas. */
function encodeBmp(canvas: HTMLCanvasElement): Blob {
  const source = flattenOntoWhite(canvas);
  const ctx = source.getContext('2d');
  if (!ctx) throw new Error('Canvas is not supported in this browser');
  const { width, height } = source;
  const pixels = ctx.getImageData(0, 0, width, height).data;

  const rowSize = Math.floor((24 * width + 31) / 32) * 4;
  const pixelArraySize = rowSize * height;
  const fileSize = 54 + pixelArraySize;

  const buffer = new ArrayBuffer(fileSize);
  const view = new DataView(buffer);

  // BITMAPFILEHEADER
  view.setUint8(0, 0x42); // 'B'
  view.setUint8(1, 0x4d); // 'M'
  view.setUint32(2, fileSize, true);
  view.setUint32(6, 0, true);
  view.setUint32(10, 54, true);

  // BITMAPINFOHEADER
  view.setUint32(14, 40, true);
  view.setInt32(18, width, true);
  view.setInt32(22, height, true); // positive height = bottom-up row order
  view.setUint16(26, 1, true);
  view.setUint16(28, 24, true);
  view.setUint32(30, 0, true); // BI_RGB, no compression
  view.setUint32(34, pixelArraySize, true);
  view.setInt32(38, 2835, true); // ~72 DPI
  view.setInt32(42, 2835, true);
  view.setUint32(46, 0, true);
  view.setUint32(50, 0, true);

  let offset = 54;
  for (let y = height - 1; y >= 0; y--) {
    for (let x = 0; x < width; x++) {
      const i = (y * width + x) * 4;
      view.setUint8(offset++, pixels[i + 2]); // B
      view.setUint8(offset++, pixels[i + 1]); // G
      view.setUint8(offset++, pixels[i]); // R
    }
    for (let p = 0; p < rowSize - width * 3; p++) view.setUint8(offset++, 0);
  }

  return new Blob([buffer], { type: 'image/bmp' });
}

/** Wraps a PNG-encoded square image in a minimal ICO container (the "PNG-in-ICO" format every OS since Vista reads). */
async function encodeIco(canvas: HTMLCanvasElement): Promise<Blob> {
  const size = Math.min(256, Math.max(canvas.width, canvas.height));
  const squared = document.createElement('canvas');
  squared.width = size;
  squared.height = size;
  const ctx = squared.getContext('2d');
  if (!ctx) throw new Error('Canvas is not supported in this browser');

  const scale = Math.min(size / canvas.width, size / canvas.height);
  const drawWidth = canvas.width * scale;
  const drawHeight = canvas.height * scale;
  ctx.drawImage(canvas, (size - drawWidth) / 2, (size - drawHeight) / 2, drawWidth, drawHeight);

  const pngBlob = await canvasToBlob(squared, 'image/png');
  const pngBuffer = await pngBlob.arrayBuffer();

  const header = new ArrayBuffer(22);
  const view = new DataView(header);
  view.setUint16(0, 0, true); // reserved
  view.setUint16(2, 1, true); // type: icon
  view.setUint16(4, 1, true); // image count
  view.setUint8(6, size >= 256 ? 0 : size); // width (0 = 256)
  view.setUint8(7, size >= 256 ? 0 : size); // height (0 = 256)
  view.setUint8(8, 0); // palette size
  view.setUint8(9, 0); // reserved
  view.setUint16(10, 1, true); // color planes
  view.setUint16(12, 32, true); // bits per pixel
  view.setUint32(14, pngBuffer.byteLength, true);
  view.setUint32(18, 22, true); // offset to image data

  return new Blob([header, pngBuffer], { type: 'image/x-icon' });
}

/** quality: 1-100, only meaningful for lossy formats (JPEG/WebP). */
export async function convertImage(
  canvas: HTMLCanvasElement,
  format: ImageOutputFormat,
  quality: number,
): Promise<Blob> {
  const meta = getFormatMeta(format);
  const q = Math.min(1, Math.max(0.01, quality / 100));

  switch (format) {
    case 'png':
      return canvasToBlob(canvas, meta.mimeType);
    case 'jpeg':
      return canvasToBlob(flattenOntoWhite(canvas), meta.mimeType, q);
    case 'webp':
      return canvasToBlob(canvas, meta.mimeType, q);
    case 'bmp':
      return encodeBmp(canvas);
    case 'ico':
      return encodeIco(canvas);
    default:
      throw new Error(`Unsupported format: ${format}`);
  }
}

export function formatBytes(bytes: number): string {
  if (bytes < 1024) return `${bytes} B`;
  const units = ['KB', 'MB', 'GB'];
  let value = bytes / 1024;
  let unitIndex = 0;
  while (value >= 1024 && unitIndex < units.length - 1) {
    value /= 1024;
    unitIndex++;
  }
  return `${value.toFixed(value >= 10 ? 0 : 1)} ${units[unitIndex]}`;
}
