export type ImageOutputFormat = 'png' | 'jpeg' | 'webp' | 'bmp' | 'ico';

export interface ImageFormatMeta {
  id: ImageOutputFormat;
  label: string;
  mimeType: string;
  extension: string;
  supportsQuality: boolean;
  supportsTransparency: boolean;
  description: string;
}

// PNG/JPEG/WebP are encoded natively via canvas.toBlob(); BMP and ICO have no
// browser encoder at all, so those two are hand-rolled in convert.ts.
export const IMAGE_OUTPUT_FORMATS: ImageFormatMeta[] = [
  {
    id: 'png',
    label: 'PNG',
    mimeType: 'image/png',
    extension: 'png',
    supportsQuality: false,
    supportsTransparency: true,
    description: 'Lossless with transparency support. Best for graphics, screenshots, and logos.',
  },
  {
    id: 'jpeg',
    label: 'JPEG',
    mimeType: 'image/jpeg',
    extension: 'jpg',
    supportsQuality: true,
    supportsTransparency: false,
    description: 'Lossy, no transparency. Best for photos — usually the smallest file size.',
  },
  {
    id: 'webp',
    label: 'WebP',
    mimeType: 'image/webp',
    extension: 'webp',
    supportsQuality: true,
    supportsTransparency: true,
    description: 'Modern format with transparency support — typically smaller than JPEG or PNG at similar quality.',
  },
  {
    id: 'bmp',
    label: 'BMP',
    mimeType: 'image/bmp',
    extension: 'bmp',
    supportsQuality: false,
    supportsTransparency: false,
    description: 'Uncompressed, no transparency. Very large files — mainly for legacy compatibility.',
  },
  {
    id: 'ico',
    label: 'ICO',
    mimeType: 'image/x-icon',
    extension: 'ico',
    supportsQuality: false,
    supportsTransparency: true,
    description: 'Windows icon container. Image is squared and capped at 256×256 — handy for favicons.',
  },
];

export function getFormatMeta(id: ImageOutputFormat): ImageFormatMeta {
  const meta = IMAGE_OUTPUT_FORMATS.find((f) => f.id === id);
  if (!meta) throw new Error(`Unknown image format: ${id}`);
  return meta;
}
